//! The Sparkplug conformance vectors in `tests/conformance/sparkplug/` (generated by the
//! independent Python reference in that folder, on Google's protobuf runtime): the Rust codec
//! must produce the same bytes and accept and reject the same inputs.
//!
//! `OPENCAP_BLESS=1 cargo test -p opencap-north-sparkplug --test vectors descriptor` rewrites
//! the descriptor set the Python reference loads, after the vendored .proto changed.

use std::path::PathBuf;

fn vectors_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../../tests/conformance/sparkplug")
}

#[test]
fn descriptor_set_is_the_vendored_proto() {
    let built: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/sparkplug_b.desc"));
    let path = vectors_dir().join("sparkplug_b.desc");
    if std::env::var_os("OPENCAP_BLESS").is_some() {
        std::fs::write(&path, built).unwrap();
    }
    let committed = std::fs::read(&path).expect("tests/conformance/sparkplug/sparkplug_b.desc");
    assert!(committed == built, "{} is stale: rerun with OPENCAP_BLESS=1", path.display());
}

// --- replaying the vectors ----------------------------------------------------------------------

use base64::Engine as _;
use opencap_core::value::{Quality, Value};
use opencap_north_sparkplug::command::{classify, NOT_TRUE, READ_ONLY};
use opencap_north_sparkplug::datatype::{datatype_for, decode, element_of};
use opencap_north_sparkplug::message::{
    birth_metric, data_metric, dbirth, ddata, ddeath, encode_payload, metric_name, nbirth, ndeath, AliasAllocator,
    BdSeq, NodeAliases, Sample, Seq, TagMeta,
};
use opencap_north_sparkplug::state::HostState;
use opencap_north_sparkplug::topic::{MessageType, Topic};
use opencap_north_sparkplug::{CodecError, DataType, Metric};
use prost::Message as _;
use serde_json::Value as J;

fn load(name: &str) -> J {
    let text = std::fs::read_to_string(vectors_dir().join(name)).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn b64(bytes: &[u8]) -> String {
    base64::engine::general_purpose::STANDARD.encode(bytes)
}

fn unb64(s: &J) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(s.as_str().unwrap()).unwrap()
}

fn value_of(j: &J) -> Option<Value> {
    Some(match j {
        J::Null => return None,
        J::Bool(b) => Value::Bool(*b),
        J::Number(n) if n.is_i64() => Value::Int(n.as_i64().unwrap()),
        J::Number(n) if n.is_u64() => Value::UInt(n.as_u64().unwrap()),
        J::Number(n) => Value::Float(n.as_f64().unwrap()),
        J::String(s) => Value::Str(s.clone()),
        J::Array(items) => Value::List(items.iter().map(|i| value_of(i).unwrap()).collect()),
        J::Object(_) => panic!("object value in a vector"),
    })
}

fn quality_of(s: &J) -> Quality {
    match s.as_str().unwrap() {
        "good" => Quality::Good,
        "bad_comm" => Quality::BadComm,
        "bad_config" => Quality::BadConfig,
        "bad_decode" => Quality::BadDecode,
        "stale" => Quality::Stale,
        other => panic!("quality {other}"),
    }
}

/// Run `f` with the vector's sample (the value is owned here, borrowed by `Sample`).
fn with_sample<T>(j: &J, f: impl FnOnce(&Sample) -> T) -> T {
    let value = value_of(&j["value"]);
    let s = Sample { value: value.as_ref(), quality: quality_of(&j["quality"]), ts_ms: j["ts_ms"].as_u64().unwrap() };
    f(&s)
}

fn tag_birth(tag: &J, alias: u64, sample: &J) -> Result<Metric, CodecError> {
    let datatype = datatype_for(
        tag["dtype"].as_str().unwrap(),
        tag["scaled"].as_bool().unwrap(),
        tag["array"].as_bool().unwrap(),
    )?;
    let eng_range = tag.get("eng_range").map(|r| (r[0].as_f64().unwrap(), r[1].as_f64().unwrap()));
    let meta = TagMeta {
        name: metric_name(tag["name"].as_str().unwrap()),
        alias,
        datatype,
        units: tag.get("units").map(|u| u.as_str().unwrap().to_string()),
        eng_range,
    };
    with_sample(sample, |s| birth_metric(&meta, s))
}

/// The value a metric of `dt` reads back as: floats rounded to the datatype's precision.
fn normalized(dt: DataType, v: Value) -> Value {
    let el = element_of(dt).unwrap_or(dt);
    let f = |v: Value| match (el, v.as_f64()) {
        (DataType::Float, Some(x)) => Value::Float(f64::from(x as f32)),
        (DataType::Double, Some(x)) => Value::Float(x),
        (_, _) => v,
    };
    match v {
        Value::List(items) => Value::List(items.into_iter().map(f).collect()),
        v => f(v),
    }
}

#[test]
fn metric_vectors() {
    let doc = load("metrics.json");
    let mut failures = vec![];
    for case in doc["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let tag = &case["tag"];
        let alias = case["alias"].as_u64().unwrap();
        let built = if case["kind"] == "birth" {
            tag_birth(tag, alias, &case["sample"])
        } else {
            datatype_for(
                tag["dtype"].as_str().unwrap(),
                tag["scaled"].as_bool().unwrap(),
                tag["array"].as_bool().unwrap(),
            )
            .and_then(|dt| {
                with_sample(&case["sample"], |s| data_metric(alias, dt, s, case["with_quality"].as_bool().unwrap()))
            })
        };
        match (case.get("error"), built) {
            (Some(_), Err(_)) => {}
            (Some(e), Ok(_)) => failures.push(format!("{name}: accepted, the reference says {e}")),
            (None, Err(e)) => failures.push(format!("{name}: rejected ({e}), the reference accepts it")),
            (None, Ok(m)) => {
                if b64(&m.encode_to_vec()) != case["metric_b64"].as_str().unwrap() {
                    failures.push(format!("{name}: bytes differ\n  rust: {m:?}\n  want: {}", case["decoded"]));
                    continue;
                }
                // and it reads back as the value that went in
                let dt = datatype_for(
                    tag["dtype"].as_str().unwrap(),
                    tag["scaled"].as_bool().unwrap(),
                    tag["array"].as_bool().unwrap(),
                )
                .unwrap();
                if let (Some(v), Some(want)) = (&m.value, value_of(&case["sample"]["value"])) {
                    let got = decode(dt, v).unwrap();
                    if got != normalized(dt, want.clone()) {
                        failures.push(format!("{name}: decodes to {got:?}, wrote {want:?}"));
                    }
                }
            }
        }
    }
    assert!(failures.is_empty(), "{} metric vector(s) failed:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn message_vectors() {
    let doc = load("messages.json");
    let (group, edge) = (doc["group"].as_str().unwrap(), doc["edge_node"].as_str().unwrap());
    let (mut seq, mut bd, mut aliases) = (Seq::default(), BdSeq::default(), AliasAllocator::default());
    let node = aliases.node();
    let mut tag_alias = std::collections::HashMap::new();
    let mut checked = 0;
    for step in doc["steps"].as_array().unwrap() {
        let op = step["op"].as_str().unwrap();
        let ts = step["ts_ms"].as_u64().unwrap();
        let device = step.get("device").and_then(J::as_str);
        let kind = MessageType::parse(step["kind"].as_str().unwrap()).unwrap();
        let topic = match device {
            Some(d) => Topic::device(group, kind, edge, d),
            None => Topic::node(group, kind, edge),
        }
        .unwrap();
        assert_eq!(topic.to_string(), step["topic"].as_str().unwrap(), "{op}");
        assert_eq!(
            (u64::from(kind.qos()), false),
            (step["qos"].as_u64().unwrap(), step["retain"].as_bool().unwrap()),
            "{op}"
        );
        let payload = match op {
            "ndeath" => {
                assert_eq!(u64::from(bd.connect()), step["bd_seq"].as_u64().unwrap(), "bdSeq of a new CONNECT");
                ndeath(ts, step["bd_seq"].as_u64().unwrap() as u8)
            }
            "nbirth" => {
                assert_eq!(u64::from(seq.birth()), step["seq"].as_u64().unwrap());
                let want = NodeAliases {
                    bd_seq: step["aliases"]["bd_seq"].as_u64().unwrap(),
                    rebirth: step["aliases"]["rebirth"].as_u64().unwrap(),
                };
                assert_eq!(node, want, "node aliases come first");
                nbirth(ts, step["bd_seq"].as_u64().unwrap() as u8, node, vec![])
            }
            "dbirth" => {
                let s = seq.next_seq();
                assert_eq!(u64::from(s), step["seq"].as_u64().unwrap(), "{op} {device:?}");
                let metrics = step["metrics"].as_array().unwrap().iter().map(|m| {
                    let key = (device.unwrap().to_string(), m["tag"]["name"].as_str().unwrap().to_string());
                    let alias = *tag_alias.entry(key).or_insert_with(|| aliases.alloc());
                    assert_eq!(alias, m["alias"].as_u64().unwrap(), "aliases in birth order");
                    tag_birth(&m["tag"], alias, &m["sample"]).unwrap()
                });
                dbirth(ts, s, metrics.collect())
            }
            "ddata" => {
                let s = seq.next_seq();
                assert_eq!(u64::from(s), step["seq"].as_u64().unwrap(), "{op} {device:?}");
                let metrics = step["metrics"].as_array().unwrap().iter().map(|m| {
                    let dt = DataType::from_str_name(m["datatype"].as_str().unwrap()).unwrap();
                    with_sample(&m["sample"], |smp| {
                        data_metric(m["alias"].as_u64().unwrap(), dt, smp, m["with_quality"].as_bool().unwrap())
                    })
                    .unwrap()
                });
                ddata(ts, s, metrics.collect())
            }
            "ddeath" => {
                let s = seq.next_seq();
                assert_eq!(u64::from(s), step["seq"].as_u64().unwrap(), "{op} {device:?}");
                ddeath(ts, s)
            }
            other => panic!("op {other}"),
        };
        assert_eq!(b64(&encode_payload(&payload)), step["payload_b64"].as_str().unwrap(), "{op} {device:?} at {ts}");
        checked += 1;
    }
    assert_eq!(checked, doc["steps"].as_array().unwrap().len());

    let mut s = Seq::default();
    s.birth();
    let wrap: Vec<u64> =
        (0..doc["seq_after_birth"].as_array().unwrap().len()).map(|_| u64::from(s.next_seq())).collect();
    assert_eq!(J::from(wrap), doc["seq_after_birth"]);
    let mut b = BdSeq::starting_at(254);
    assert_eq!(J::from(vec![b.connect(), b.connect(), b.connect()]), doc["bd_seq_from_254"]);
}

#[test]
fn command_vectors() {
    let doc = load("commands.json");
    for case in doc["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let alias = case["rebirth_alias"].as_u64();
        let got = Topic::parse(case["topic"].as_str().unwrap())
            .and_then(|t| classify(&t, &unb64(&case["payload_b64"]), alias));
        if case.get("error").is_some() {
            assert!(got.is_err(), "{name}: accepted {got:?}");
            continue;
        }
        let d = got.unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(J::Bool(d.rebirth), case["rebirth"], "{name}");
        let rejected: Vec<J> = d
            .rejected
            .iter()
            .map(|r| {
                let reason = match r.reason {
                    READ_ONLY => "read_only",
                    NOT_TRUE => "not_true",
                    other => panic!("{other}"),
                };
                serde_json::json!([r.metric, reason])
            })
            .collect();
        assert_eq!(J::from(rejected), case["rejected"], "{name}");
    }
}

#[test]
fn topic_vectors() {
    let doc = load("topics.json");
    for case in doc["valid"].as_array().unwrap() {
        let s = case["topic"].as_str().unwrap();
        let t = Topic::parse(s).unwrap_or_else(|e| panic!("{e}"));
        assert_eq!(t.to_string(), s);
        let p = &case["parsed"];
        let want = match p.get("state") {
            Some(h) => Topic::State { host_id: h.as_str().unwrap().into() },
            None => {
                let kind = MessageType::parse(p["kind"].as_str().unwrap()).unwrap();
                let (g, e) = (p["group"].as_str().unwrap(), p["edge_node"].as_str().unwrap());
                match p.get("device") {
                    Some(d) => {
                        Topic::Device { group: g.into(), kind, edge_node: e.into(), device: d.as_str().unwrap().into() }
                    }
                    None => Topic::Node { group: g.into(), kind, edge_node: e.into() },
                }
            }
        };
        assert_eq!(t, want, "{s}");
    }
    for s in doc["invalid"].as_array().unwrap() {
        assert!(Topic::parse(s.as_str().unwrap()).is_err(), "{s} parsed");
    }
    for case in doc["build"].as_array().unwrap() {
        let kind = MessageType::parse(case["kind"].as_str().unwrap()).unwrap();
        let (g, e) = (case["group"].as_str().unwrap(), case["edge_node"].as_str().unwrap());
        let got = match case["device"].as_str() {
            Some(d) => Topic::device(g, kind, e, d),
            None => Topic::node(g, kind, e),
        };
        match (case.get("topic"), got) {
            (Some(want), Ok(t)) => assert_eq!(t.to_string(), want.as_str().unwrap()),
            (None, Err(_)) => {}
            (want, got) => panic!("{case}: reference {want:?}, rust {got:?}"),
        }
    }
}

#[test]
fn state_vectors() {
    let doc = load("state.json");
    for case in doc["cases"].as_array().unwrap() {
        let got = HostState::parse(case["payload"].as_str().unwrap().as_bytes());
        match (case.get("error"), got) {
            (Some(_), Err(_)) => {}
            (None, Ok(s)) => {
                assert_eq!(
                    (J::Bool(s.online), J::from(s.timestamp)),
                    (case["online"].clone(), case["timestamp"].clone())
                );
            }
            (_, got) => panic!("{case}: rust {got:?}"),
        }
    }
}

#[test]
fn quality_matches_the_shared_vectors() {
    use opencap_north_sparkplug::quality::{is_null, quality_code};
    let path = vectors_dir().join("../quality/map.json");
    let doc: J = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut n = 0;
    for v in doc["vectors"].as_array().unwrap() {
        let (q, ever) = (quality_of(&v["input"]["quality"]), v["input"]["ever_good"].as_bool().unwrap());
        let want = &v["expected"]["sparkplug"];
        assert_eq!(J::from(quality_code(q, ever)), want["Quality"], "{}", v["id"]);
        assert_eq!(J::Bool(is_null(q, ever)), want["is_null"], "{}", v["id"]);
        n += 1;
    }
    assert_eq!(n, 10);
}
